import{_ as l,c as e,o as i,a3 as t}from"./chunks/framework.BusRvirq.js";const u=JSON.parse('{"title":"상호 비밀유지협약서 (Non-Disclosure Agreement)","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/public/templates/01_NDA_template.html"}]]},"headers":[],"relativePath":"public/templates/01_NDA_template.md","filePath":"public/templates/01_NDA_template.md","lastUpdated":1790810085000}'),o={name:"public/templates/01_NDA_template.md"};function r(n,a,s,h,d,p){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="상호-비밀유지협약서-non-disclosure-agreement" tabindex="-1">상호 비밀유지협약서 (Non-Disclosure Agreement) <a class="header-anchor" href="#상호-비밀유지협약서-non-disclosure-agreement" aria-label="Permalink to “상호 비밀유지협약서 (Non-Disclosure Agreement)”">​</a></h1><p>주식회사 [발주회사명] (이하 &quot;갑&quot;이라 한다)과 주식회사 엠파시 (이하 &quot;을&quot;이라 한다)는 [프로젝트명 / 사업명] (이하 &quot;본건 업무&quot;라 한다)의 추진과 관련하여 상호 제공하는 비밀정보의 보호를 위하여 다음과 같이 협약을 체결한다.</p><hr><h3 id="제1조-목적" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#제1조-목적" aria-label="Permalink to “제1조 (목적)”">​</a></h3><p>본 협약은 &quot;본건 업무&quot;의 검토, 제안, 계약 체결 및 프로젝트 수행 과정에서 일방 당사자가 상대방에게 제공하는 기술, 영업, 재무 등 일체의 기밀정보를 보호하고 누설을 방지하는 것을 목적으로 한다.</p><h3 id="제2조-비밀정보의-정의" tabindex="-1">제2조 (비밀정보의 정의) <a class="header-anchor" href="#제2조-비밀정보의-정의" aria-label="Permalink to “제2조 (비밀정보의 정의)”">​</a></h3><ol><li>&quot;비밀정보&quot;라 함은 서면, 구두, 전자적 파일, 기타 일체의 수단에 의하여 상대방에게 공개되거나 전달된 모든 유·무형의 정보로서 다음 각 호의 사항을 포함한다. <ul><li>사업 계획, 기술 사양, 아키텍처, 소스코드, 데이터베이스 스키마, 알고리즘, 시스템 구성도</li><li>고객 명단, 재무 데이터, 원가 구조, 영업 전략, 견적 조건</li><li>&quot;본건 업무&quot;와 관련하여 제공되는 시연 데이터, 실데이터 샘플, AI 학습 및 연계 데이터</li></ul></li><li>서면이나 파일 형태로 전달될 경우 &quot;비밀&quot;, &quot;Confidential&quot;, &quot;대외비&quot; 등의 표식이 있어야 하며, 구두로 전달된 경우 14일 이내에 비밀임을 서면으로 통지하여야 한다. 다만, 정보의 성격상 통상적인 주의 의무를 가진 자라면 비밀임을 알 수 있는 정보는 표식이 없더라도 비밀정보로 인정한다.</li></ol><h3 id="제3조-비밀정보의-예외" tabindex="-1">제3조 (비밀정보의 예외) <a class="header-anchor" href="#제3조-비밀정보의-예외" aria-label="Permalink to “제3조 (비밀정보의 예외)”">​</a></h3><p>다음 각 호에 해당하는 정보는 본 협약상 비밀정보로 보지 아니한다.</p><ol><li>공개 시점에 이미 공지의 사실이 되었거나 일반에 알려져 있던 정보</li><li>정보 공개 전 이미 보유하고 있었음을 객관적 서면 자료로 입증할 수 있는 정보</li><li>비밀유지 의무를 위반하지 아니한 제3자로부터 정당하게 취득한 정보</li><li>상대방의 비밀정보를 참조하지 아니하고 독자적으로 개발하였음을 입증할 수 있는 정보</li><li>관련 법령, 법원 또는 정부 기관의 적법한 명령이나 요청에 의하여 공개가 강제되는 정보 (단, 사전에 상대방에게 즉시 서면 통지하여야 함)</li></ol><h3 id="제4조-비밀유지-의무-및-사용-제한" tabindex="-1">제4조 (비밀유지 의무 및 사용 제한) <a class="header-anchor" href="#제4조-비밀유지-의무-및-사용-제한" aria-label="Permalink to “제4조 (비밀유지 의무 및 사용 제한)”">​</a></h3><ol><li>양 당사자는 제공받은 비밀정보를 &quot;본건 업무&quot; 목적 이외의 어떠한 용도로도 사용할 수 없으며, 상대방의 사전 서면 승낙 없이 제3자에게 누설, 공개, 배포, 복제할 수 없다.</li><li>정보 수령자는 비밀정보를 업무상 알 필요가 있는 최소한의 임직원 및 공인된 자문 인력에게만 공개하여야 하며, 이들에게 본 협약과 동일한 수준의 비밀유지 의무를 부담시켜야 한다.</li><li>양 당사자는 자사의 중요한 기밀정보를 보호하는 것과 동일한 수준(최소한의 상당한 주의 의무)으로 상대방의 비밀정보를 관리하여야 한다.</li></ol><h3 id="제5조-정보의-반환-및-파기" tabindex="-1">제5조 (정보의 반환 및 파기) <a class="header-anchor" href="#제5조-정보의-반환-및-파기" aria-label="Permalink to “제5조 (정보의 반환 및 파기)”">​</a></h3><ol><li>본 협약이 만료되거나 일방 당사자의 서면 반환 요청이 있을 경우, 정보 수령자는 요청일로부터 [14]일 이내에 제공받은 모든 비밀정보의 원본, 사본, 요약본, 분석 자료를 지체 없이 반환하거나 영구 파기하여야 한다.</li><li>전자적 형태로 저장된 파일은 복구가 불가능한 기술적 방법으로 완전 삭제하여야 하며, 상대방의 요청이 있을 경우 대표자 명의의 &quot;비밀정보 파기 확인서&quot;를 서면으로 교부하여야 한다.</li></ol><h3 id="제6조-손해배상" tabindex="-1">제6조 (손해배상) <a class="header-anchor" href="#제6조-손해배상" aria-label="Permalink to “제6조 (손해배상)”">​</a></h3><p>일방 당사자가 본 협약의 의무를 위반하여 상대방에게 손해를 입힌 경우, 위반 당사자는 상대방이 입은 통상의 손해를 배상하여야 한다. 또한 정보의 침해가 발생하였거나 우려가 있는 경우 피해 당사자는 법원에 침해 금지 가처분 등 필요한 보전 처분을 신청할 수 있다.</p><h3 id="제7조-유효기간" tabindex="-1">제7조 (유효기간) <a class="header-anchor" href="#제7조-유효기간" aria-label="Permalink to “제7조 (유효기간)”">​</a></h3><p>본 협약은 양 당사자가 서명 또는 날인한 날로부터 효력이 발생하며, 계약 체결 여부와 무관하게 비밀정보 제공일로부터 [3]년간 유효하다.</p><h3 id="제8조-관할-법원" tabindex="-1">제8조 (관할 법원) <a class="header-anchor" href="#제8조-관할-법원" aria-label="Permalink to “제8조 (관할 법원)”">​</a></h3><p>본 협약과 관련하여 분쟁이 발생할 경우 상호 원만히 협의하여 해결하되, 협의가 이루어지지 아니할 경우 [서울중앙지방법원 또는 피고의 소재지 관할 법원]을 제1심 전속관할 법원으로 한다.</p><hr><p><strong>체결일자: 202 년 월 일</strong></p><p><strong>[갑] 발주회사</strong></p><ul><li>회사명: 주식회사 [발주회사명]</li><li>사업자등록번호: [ - - ]</li><li>주소: [ ]</li><li>대표이사: [ ] (인)</li></ul><p><strong>[을] 수주회사</strong></p><ul><li>회사명: 주식회사 엠파시</li><li>사업자등록번호: [ - - ]</li><li>주소: [ ]</li><li>대표이사: [ ] (인)</li></ul>',26)])])}const m=l(o,[["render",r]]);export{u as __pageData,m as default};
